#!/bin/bash
# LG gram Style (ALC298, SSID 1854:049x) speaker amp init/enable via AppleALC alc-verb.
# Sequence ported from Linux sound/hda/codecs/realtek/alc269.c ALC298_FIXUP_LG_GRAM_STYLE_14.
# usage: lg-gram-amp.sh [init|enable|disable]   (default: init + enable)
V=/usr/local/bin/alc-verb
w(){ "$V" -q 0x20 "$1" "$2" >/dev/null || { echo "alc-verb failed: $1 $2" >&2; exit 1; }; }
coef(){ w 0x500 "$1"; w 0x400 "$2"; }                      # alc_write_coef_idx
cw(){ w 0x500 0x23; w "$1" "$2"; w 0x400 0x00; w 0x400 "$3"; w 0x400 0xb011; }  # coef_write(verb,idx,val)
AMPS="0x38 0x39 0x3c 0x3d"
seq_38="0x423 0xe1 0x00  0x420 0x12 0x6f  0x420 0x14 0x00  0x420 0x1b 0x01  0x420 0x1d 0x01  0x420 0x1f 0xfe  0x420 0x21 0x00  0x420 0x22 0x10  0x420 0x3d 0x05  0x420 0x3f 0x03  0x420 0x50 0x2c  0x420 0x76 0x0e  0x420 0x7c 0x4a  0x420 0x81 0x03  0x423 0x99 0x03  0x423 0xa4 0xb5  0x423 0xa5 0x01  0x423 0xba 0x94"
seq_39="0x423 0xe1 0x00  0x420 0x12 0x6f  0x420 0x14 0x00  0x420 0x1b 0x02  0x420 0x1d 0x02  0x420 0x1f 0xfd  0x420 0x21 0x01  0x420 0x22 0x10  0x420 0x3d 0x05  0x420 0x3f 0x03  0x420 0x50 0x2c  0x420 0x76 0x0e  0x420 0x7c 0x4a  0x420 0x81 0x03  0x423 0x99 0x03  0x423 0xa4 0xb5  0x423 0xa5 0x01  0x423 0xba 0x94"
seq_3c="0x423 0xe1 0x00  0x420 0x12 0x6f  0x420 0x14 0x00  0x420 0x1b 0x01  0x420 0x1d 0x01  0x420 0x1f 0xfe  0x420 0x21 0x00  0x420 0x22 0x10  0x420 0x3d 0x05  0x420 0x3f 0x03  0x420 0x50 0x2c  0x420 0x76 0x0e  0x420 0x7c 0x4a  0x420 0x81 0x03  0x423 0xba 0x8d"
seq_3d="0x423 0xe1 0x00  0x420 0x12 0x6f  0x420 0x14 0x00  0x420 0x1b 0x02  0x420 0x1d 0x02  0x420 0x1f 0xfd  0x420 0x21 0x01  0x420 0x22 0x10  0x420 0x3d 0x05  0x420 0x3f 0x03  0x420 0x50 0x2c  0x420 0x76 0x0e  0x420 0x7c 0x4a  0x420 0x81 0x03  0x423 0xba 0x8d"
run(){ set -- $1; while [ $# -ge 3 ]; do cw "$1" "$2" "$3"; shift 3; done; }
init(){ for a in $AMPS; do coef 0x22 $a; cw 0x420 0x00 0x01; cw 0x423 0xff 0x00; cw 0x420 0x3a 0x80
  case $a in 0x38) run "$seq_38";; 0x39) run "$seq_39";; 0x3c) run "$seq_3c";; 0x3d) run "$seq_3d";; esac; coef 0x89 0x0; done; }
enable(){ for a in $AMPS; do coef 0x22 $a; cw 0x420 0x3a 0x81; cw 0x423 0xff 0x01; done; }
disable(){ for a in $AMPS; do coef 0x22 $a; cw 0x423 0xff 0x00; cw 0x420 0x3a 0x80; done; }
case "${1:-all}" in init) init;; enable) enable;; disable) disable;; all) init; enable;; *) echo "usage: $0 [init|enable|disable]"; exit 2;; esac
echo "lg-gram-amp: ${1:-all} done"
